class Orders {
  #items = [];
  add(order) {
    if (this.#items.length >= MAX_ORDERS) throw new RangeError('order limit reached');
    this.#items.push(order);
  }
  get size() { return this.#items.length; }
  *[Symbol.iterator]() { yield* this.#items; }
  snapshot() { return Object.freeze([...this.#items]); }   // copy, never #items
}
